 35	    /// just enqueues the original inner command.
 36	    /// </summary>
 37	    /// <param name="message">IdentifiedCommand which contains both original command & request ID</param>
 38	    /// <returns>Return value of inner command or default value if request same ID was found</returns>
 39	    public async Task<R> Handle(IdentifiedCommand<T, R> message, CancellationToken cancellationToken)
 40	    {
 41	        var alreadyExists = await _requestManager.ExistAsync(message.Id);
 42	        if (alreadyExists)
 43	        {
 44	            return CreateResultForDuplicateRequest();
 45	        }
 46	        else
 47	        {
 48	            await _requestManager.CreateRequestForCommandAsync<T>(message.Id);
 49	            try
 50	            {
 51	                var command = message.Command;
 52	                var commandName = command.GetGenericTypeName();
 53	                var idProperty = string.Empty;
 54	                var commandId = string.Empty;
 55	
 56	                switch (command)
 57	                {
 58	                    case CreateOrderCommand createOrderCommand:
 59	                        idProperty = nameof(createOrderCommand.UserId);
 60	                        commandId = createOrderCommand.UserId;
 61	                        break;
 62	
 63	                    case CancelOrderCommand cancelOrderCommand:
 64	                        idProperty = nameof(cancelOrderCommand.OrderNumber);
 65	                        commandId = $"{cancelOrderCommand.OrderNumber}";
 66	                        break;
 67	
 68	                    case ShipOrderCommand shipOrderCommand:
 69	                        idProperty = nameof(shipOrderCommand.OrderNumber);
 70	                        commandId = $"{shipOrderCommand.OrderNumber}";
 71	                        break;
 72	
 73	                    default:
 74	                        idProperty = "Id?";
 75	                        commandId = "n/a";
 76	                        break;
 77	                }
 78	
 79	                _logger.LogInformation(
 80	                    "Sending command: {CommandName} - {IdProperty}: {CommandId} ({@Command})",
 81	                    commandName,
 82	                    idProperty,
 83	                    commandId,
 84	                    command);
 85	
 86	                // Send the embedded business command to mediator so it runs its related CommandHandler 
 87	                var result = await _mediator.Send(command, cancellationToken);
 88	
 89	                _logger.LogInformation(
 90	                    "Command result: {@Result} - {CommandName} - {IdProperty}: {CommandId} ({@Command})",
 91	                    result,
 92	                    commandName,
 93	                    idProperty,
 94	                    commandId,
 95	                    command);
 96	
 97	                return result;
 98	            }
 99	            catch
100	            {
101	                return default;
102	            }
103	        }
104	    }
105	}
  1	﻿namespace eShop.Ordering.Infrastructure.Idempotency;
  2	
  3	public class RequestManager : IRequestManager
  4	{
  5	    private readonly OrderingContext _context;
  6	
  7	    public RequestManager(OrderingContext context)
  8	    {
  9	        _context = context ?? throw new ArgumentNullException(nameof(context));
 10	    }
 11	
 12	
 13	    public async Task<bool> ExistAsync(Guid id)
 14	    {
 15	        var request = await _context.
 16	            FindAsync<ClientRequest>(id);
 17	
 18	        return request != null;
 19	    }
 20	
 21	    public async Task CreateRequestForCommandAsync<T>(Guid id)
 22	    {
 23	        var exists = await ExistAsync(id);
 24	
 25	        var request = exists ?
 26	            throw new OrderingDomainException($"Request with {id} already exists") :
 27	            new ClientRequest()
 28	            {
 29	                Id = id,
 30	                Name = typeof(T).Name,
 31	                Time = DateTime.UtcNow
 32	            };
 33	
 34	        _context.Add(request);
 35	
 36	        await _context.SaveChangesAsync();
 37	    }
 38	}
 20	    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken cancellationToken)
 21	    {
 22	        var response = default(TResponse);
 23	        var typeName = request.GetGenericTypeName();
 24	
 25	        try
 26	        {
 27	            if (_dbContext.HasActiveTransaction)
 28	            {
 29	                return await next();
 30	            }
 31	
 32	            var strategy = _dbContext.Database.CreateExecutionStrategy();
 33	
 34	            await strategy.ExecuteAsync(async () =>
 35	            {
 36	                Guid transactionId;
 37	
 38	                await using var transaction = await _dbContext.BeginTransactionAsync();
 39	                using (_logger.BeginScope(new List<KeyValuePair<string, object>> { new("TransactionContext", transaction.TransactionId) }))
 40	                {
 41	                    _logger.LogInformation("Begin transaction {TransactionId} for {CommandName} ({@Command})", transaction.TransactionId, typeName, request);
 42	
 43	                    response = await next();
 44	
 45	                    _logger.LogInformation("Commit transaction {TransactionId} for {CommandName}", transaction.TransactionId, typeName);
 46	
 47	                    await _dbContext.CommitTransactionAsync(transaction);
 48	
 49	                    transactionId = transaction.TransactionId;
 50	                }
 51	
 52	                await _orderingIntegrationEventService.PublishEventsThroughEventBusAsync(transactionId);
 53	            });
 54	
 55	            return response;
 56	        }
 57	        catch (Exception ex)
 58	        {
 59	            _logger.LogError(ex, "Error Handling transaction for {CommandName} ({@Command})", typeName, request);
 60	
 61	            throw;
 62	        }
 63	    }
 64	}
 13	    public async Task PublishEventsThroughEventBusAsync(Guid transactionId)
 14	    {
 15	        var pendingLogEvents = await _eventLogService.RetrieveEventLogsPendingToPublishAsync(transactionId);
 16	
 17	        foreach (var logEvt in pendingLogEvents)
 18	        {
 19	            _logger.LogInformation("Publishing integration event: {IntegrationEventId} - ({@IntegrationEvent})", logEvt.EventId, logEvt.IntegrationEvent);
 20	
 21	            try
 22	            {
 23	                await _eventLogService.MarkEventAsInProgressAsync(logEvt.EventId);
 24	                await _eventBus.PublishAsync(logEvt.IntegrationEvent);
 25	                await _eventLogService.MarkEventAsPublishedAsync(logEvt.EventId);
 26	            }
 27	            catch (Exception ex)
 28	            {
 29	                _logger.LogError(ex, "Error publishing integration event: {IntegrationEventId}", logEvt.EventId);
 30	
 31	                await _eventLogService.MarkEventAsFailedAsync(logEvt.EventId);
 32	            }
 33	        }
 34	    }
 35	
 36	    public async Task AddAndSaveEventAsync(IntegrationEvent evt)
 37	    {
 38	        _logger.LogInformation("Enqueuing integration event {IntegrationEventId} to repository ({@IntegrationEvent})", evt.Id, evt);
 39	
 40	        await _eventLogService.SaveEventAsync(evt, _orderingContext.GetCurrentTransaction());
 41	    }
 42	}

