     4	{
     5	    public async Task SendAll(IEnumerable<WebhookSubscription> receivers, WebhookData data)
     6	    {
     7	        var client = httpClientFactory.CreateClient();
     8	        var json = JsonSerializer.Serialize(data);
     9	        var tasks = receivers.Select(r => OnSendData(r, json, client));
    10	        await Task.WhenAll(tasks);
    11	    }
    12	
    13	    private Task OnSendData(WebhookSubscription subs, string jsonData, HttpClient client)
    14	    {
    15	        var request = new HttpRequestMessage()
    16	        {
    17	            RequestUri = new Uri(subs.DestUrl, UriKind.Absolute),
    18	            Method = HttpMethod.Post,
    19	            Content = new StringContent(jsonData, Encoding.UTF8, "application/json")
    20	        };
    21	
    22	        if (!string.IsNullOrWhiteSpace(subs.Token))
    23	        {
    24	            request.Headers.Add("X-eshop-whtoken", subs.Token);
    25	        }
    26	
    27	        if (logger.IsEnabled(LogLevel.Debug))
    28	        {
    29	            logger.LogDebug("Sending hook to {DestUrl} of type {Type}", subs.DestUrl, subs.Type);
    30	        }
    31	
    32	        return client.SendAsync(request);
    33	    }
