    13	        bool.TryParse(configuration["ValidateToken"], out var validateToken);
    14	        var tokenToValidate = configuration["WebhookClientOptions:Token"];
    15	
    16	        app.MapMethods("/check", [HttpMethods.Options], Results<Ok, BadRequest<string>> ([FromHeader(Name = webhookCheckHeader)] string value, HttpResponse response) =>
    17	        {
    18	            if (!validateToken || value == tokenToValidate)
    19	            {
    20	                if (!string.IsNullOrWhiteSpace(value))
    21	                {
    22	                    response.Headers.Append(webhookCheckHeader, value);
    23	                }
    24	
    25	                return TypedResults.Ok();
    26	            }
    27	
